// Assemble all data for publishing
const titleData = JSON.parse($node['Step 2: Title & Hooks (GPT-5.2)'].json.choices[0].message.content);
const blogData = JSON.parse($node['Step 4: Blog Body (Sonnet 4.6)'].json.content[0].text);
const videoId = $node['Webhook Trigger'].json.body.video_id;

// TODO: Upload hero image to R2 and get URL
const heroImageUrl = 'HERO_IMAGE_R2_URL';

return [{
  json: {
    videoId,
    title: titleData.title,
    hook: titleData.hook,
    seoDesc: titleData.seo_description,
    heroImage: heroImageUrl,
    intro: blogData.intro,
    sections: blogData.sections,
    conclusion: blogData.conclusion,
    tags: blogData.tags,
    keywords: titleData.keywords
  }
}];
